// =====================================
// Fungsi bantuan
// =====================================

function dapatkanMP(id) {
  return DATA_MP.find(mp => mp.id === id);
}

function senaraiMPMengikutParti(parti) {
  return DATA_MP.filter(mp => mp.parti === parti);
}

function senaraiMPMengikutNegeri(negeri) {
  return DATA_MP.filter(mp => mp.negeri === negeri);
}

function jumlahKerusiParti(parti) {
  return DATA_MP.filter(mp => mp.parti === parti).length;
}